(function(){
  function esc(s){ return String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
  function cls(chars){
    var u={}, order=[];
    for(var i=0;i<chars.length;i++){ var c=chars[i]; if(!(c in u)){u[c]=1;order.push(c);} }
    order.sort();
    var parts=[], i=0;
    while(i<order.length){
      var j=i;
      while(j+1<order.length && order[j+1].charCodeAt(0)-order[j].charCodeAt(0)===1){ j++; }
      if(j>i){ parts.push(order[i]+'-'+order[j]); } else { parts.push(order[i]); }
      i=j+1;
    }
    if(parts.length===1 && parts[0].indexOf('-')<0) return parts[0];
    return '['+parts.join('')+']';
  }
  function code(c){ return c.charCodeAt(0); }
  function pre(s1,s2){ var i=0; while(i<s1.length&&i<s2.length&&s1[i]===s2[i])i++; return i; }
  function commonPrefix(a){ var p=0; for(var i=1;i<a.length;i++){ var n=pre(a[0],a[i]); if(n<p)p=n; else p=n; } return a[0].slice(0,p); }
  function commonSuffix(a){ var sufs=a.map(function(s){return s.split('').reverse().join('');}); var p=0; for(var i=1;i<sufs.length;i++){ var n=pre(sufs[0],sufs[i]); if(n<p)p=n; else p=n; } var k=a[0].length-p; return a[0].slice(k); }
  function fromSamples(input, opt){
    opt=opt||{};
    var ss=String(input||'').split(/\r?\n/).map(function(s){return s.replace(/\r$/,'')}).filter(function(s){return s.length;});
    if(!ss.length) return {error:'请输入示例字符串'};
    if(ss.length===1) return {value:esc(ss[0])};
    var pre=commonPrefix(ss), suf=commonSuffix(ss);
    var mids=ss.map(function(s){return s.slice(pre.length, s.length-suf.length);});
    var body;
    var sameLen=mids.every(function(m){return m.length===mids[0].length;});
    if(mids.every(function(m){return m.length===0;})) body='';
    else if(opt.alternation || !sameLen){
      body='('+mids.map(esc).join('|')+')';
    } else {
      body=mids[0].split('').map(function(_,i){ var col=mids.map(function(m){return m[i];}); return cls(col); }).join('');
    }
    return {value: esc(pre)+body+esc(suf)};
  }
  var API={fromSamples:fromSamples, esc:esc};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__GrexForge__=API;
})();
